<?php
declare(strict_types=1);
namespace KMM\Core;
/** The business schema is installed with a fresh v0.1.3 instance; no automatic upgrade of existing data. */
final class BusinessSchema {
    public static function statements(): array {return [
        "CREATE TABLE IF NOT EXISTS companies (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,display_name VARCHAR(240) NOT NULL,legal_name VARCHAR(240) NULL,description TEXT NULL,website_url VARCHAR(2000) NULL,visibility VARCHAR(20) NOT NULL DEFAULT 'draft',seed_key VARCHAR(64) NULL UNIQUE,revision INT UNSIGNED NOT NULL DEFAULT 1,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_company_status(visibility,display_name),CONSTRAINT fk_company_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS sources (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,title VARCHAR(500) NOT NULL,source_url VARCHAR(2000) NULL,source_type VARCHAR(40) NOT NULL,publication_state VARCHAR(20) NOT NULL DEFAULT 'private',observed_on DATE NULL,note TEXT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,archived_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_source_type(source_type,observed_on)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS brands (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(240) NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,archived_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_brand_company(company_id),CONSTRAINT fk_brand_company FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS company_locations (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(240) NOT NULL,kind VARCHAR(30) NOT NULL,address VARCHAR(800) NULL,verification_state VARCHAR(20) NOT NULL DEFAULT 'unconfirmed',latitude DECIMAL(9,6) NULL,longitude DECIMAL(9,6) NULL,source_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NULL,verified_on DATE NULL,note TEXT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,archived_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_loc_company(company_id),INDEX idx_loc_verification(verification_state),CONSTRAINT fk_location_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_location_source FOREIGN KEY(source_id) REFERENCES sources(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS jobs (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,title VARCHAR(240) NOT NULL,category VARCHAR(40) NOT NULL,graduate_year SMALLINT UNSIGNED NOT NULL,recruitment_state VARCHAR(30) NOT NULL DEFAULT 'unverified',source_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NULL,observed_on DATE NULL,deadline_on DATE NULL,note TEXT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,archived_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_job_company(company_id),INDEX idx_job_state(recruitment_state,graduate_year),CONSTRAINT fk_job_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_job_source FOREIGN KEY(source_id) REFERENCES sources(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS job_locations (job_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,location_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,assignment_state VARCHAR(24) NOT NULL DEFAULT 'candidate',PRIMARY KEY(job_id,location_id),CONSTRAINT fk_jl_job FOREIGN KEY(job_id) REFERENCES jobs(id),CONSTRAINT fk_jl_loc FOREIGN KEY(location_id) REFERENCES company_locations(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS company_sources (company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,PRIMARY KEY(company_id,source_id),CONSTRAINT fk_company_source_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_company_source_source FOREIGN KEY(source_id) REFERENCES sources(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS business_change_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NULL,record_type VARCHAR(40) NOT NULL,record_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,operation VARCHAR(30) NOT NULL,before_json LONGTEXT NULL,after_json LONGTEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_business_event(record_type,record_id,created_at),INDEX idx_event_actor(actor_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS project_seed_records (seed_key VARCHAR(64) PRIMARY KEY,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_document VARCHAR(2000) NOT NULL,source_checked_on DATE NOT NULL,seed_version VARCHAR(50) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_seed_company FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
    ];}
}
